begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.uid(n integer)returns uuid language sql immutable as $$select ('21820000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at,raw_app_meta_data,raw_user_meta_data)
select pg_temp.uid(n),'authenticated','authenticated','library-s218-'||n||'@veyocast.test','test',now(),now(),now(),'{}','{}'from generate_series(1,3)n;
insert into public.profiles(id,display_name)select pg_temp.uid(n),'Publisher test '||n from generate_series(1,3)n;
insert into public.tenants(id,name,slug,screen_limit)values(pg_temp.uid(10),'Publisher A','library-s218-a',5),(pg_temp.uid(11),'Publisher B','library-s218-b',5);
insert into public.tenant_settings(tenant_id)values(pg_temp.uid(10)),(pg_temp.uid(11));
insert into public.tenant_memberships(tenant_id,user_id,role)values(pg_temp.uid(10),pg_temp.uid(1),'tenant_owner'),(pg_temp.uid(11),pg_temp.uid(2),'tenant_owner'),(pg_temp.uid(10),pg_temp.uid(3),'tenant_viewer');

create temporary table doc(value jsonb);grant select on doc to authenticated;
insert into doc values('{"schemaVersion":1,"artboard":{"width":1920,"height":1080,"orientation":"landscape","background":{"kind":"solid","color":"#FAFAF7"},"safeArea":{"top":64,"right":64,"bottom":64,"left":64}},"motion":{"enabled":true,"durationMs":45000,"fps":30},"elements":[],"metadata":{"fontRegistryVersion":"2026-07-24.1","tenantBrandApplied":false},"sitesPresentation":{"kind":"studio","schemaVersion":1,"rendererVersion":"sites-v11","sourceRevision":"b1cae899af19fc39908217253094c5240d7359fc","slide":{"id":"s191-fixture","name":"Typed club update","title":"Onze club","time":"","subtitle":"","location":"","duration":15,"color":"#03438a","background":"#052a55","bold":true,"italic":false,"align":"left","size":58,"context":true,"showLocation":true,"animation":"Geen","transition":"Rustig","orientation":"landscape","themeId":"onzetrots-tv","tv":{"kind":"programma","title":"Onze club","rows":[{"id":"row-0","primary":"Team 0","home":"Team 0","away":"Opponent 0","time":"14:00"},{"id":"row-1","primary":"Team 1","home":"Team 1","away":"Opponent 1","time":"14:00"},{"id":"row-2","primary":"Team 2","home":"Team 2","away":"Opponent 2","time":"14:00"},{"id":"row-3","primary":"Team 3","home":"Team 3","away":"Opponent 3","time":"14:00"},{"id":"row-4","primary":"Team 4","home":"Team 4","away":"Opponent 4","time":"14:00"},{"id":"row-5","primary":"Team 5","home":"Team 5","away":"Opponent 5","time":"14:00"},{"id":"row-6","primary":"Team 6","home":"Team 6","away":"Opponent 6","time":"14:00"},{"id":"row-7","primary":"Team 7","home":"Team 7","away":"Opponent 7","time":"14:00"},{"id":"row-8","primary":"Team 8","home":"Team 8","away":"Opponent 8","time":"14:00"},{"id":"row-9","primary":"Team 9","home":"Team 9","away":"Opponent 9","time":"14:00"},{"id":"row-10","primary":"Team 10","home":"Team 10","away":"Opponent 10","time":"14:00"},{"id":"row-11","primary":"Team 11","home":"Team 11","away":"Opponent 11","time":"14:00"},{"id":"row-12","primary":"Team 12","home":"Team 12","away":"Opponent 12","time":"14:00"},{"id":"row-13","primary":"Team 13","home":"Team 13","away":"Opponent 13","time":"14:00"},{"id":"row-14","primary":"Team 14","home":"Team 14","away":"Opponent 14","time":"14:00"},{"id":"row-15","primary":"Team 15","home":"Team 15","away":"Opponent 15","time":"14:00"},{"id":"row-16","primary":"Team 16","home":"Team 16","away":"Opponent 16","time":"14:00"}],"scale":100}}}}'::jsonb);
create temporary table result(value jsonb);grant all on result to authenticated;
set local role authenticated;select set_config('request.jwt.claim.sub',pg_temp.uid(1)::text,true);
insert into result select public.create_studio_series_v1(pg_temp.uid(10),'HTML zonder PNG',jsonb_build_array(jsonb_build_object('name','HTML zonder PNG','document',(select value from doc),'referencedAssetIds','[]'::jsonb,'commandKey',pg_temp.uid(51))),pg_temp.uid(50));
select is((public.list_publisher_studio_series_v1(pg_temp.uid(10))->>'total')::integer,0,'historical ready-only endpoint stays compatible');
select is((public.list_publisher_studio_series_v2(pg_temp.uid(10))->>'total')::integer,1,'saved HTML is visible without a raster export');
select is(jsonb_array_length(public.list_publisher_studio_series_v2(pg_temp.uid(10))->'series'->0->'members'),1,'all current members are visible');
select is(public.list_publisher_studio_series_v2(pg_temp.uid(10))#>>'{series,0,members,0,document,sitesPresentation,slide,title}','Onze club','typed HTML content is retained');
select ok(public.list_publisher_studio_series_v2(pg_temp.uid(10))#>'{series,0,members,0,exportId}'='null'::jsonb,'missing export is explicit, never faked');
select is((public.list_publisher_studio_series_v2(pg_temp.uid(10))#>>'{series,0,members,0,draftRevision}')::integer,0,'preparation can guard the exact selected draft');
select is((public.list_publisher_studio_series_v2(pg_temp.uid(10),0,'missing')->>'total')::integer,0,'search runs before pagination');
select is(jsonb_array_length(public.list_publisher_studio_series_v2(pg_temp.uid(10),8)->'series'),0,'page offset is bounded independently of export status');
select throws_ok($$select public.list_publisher_studio_series_v2(pg_temp.uid(10),-1)$$,'22023',null,'negative offsets are rejected');
create temporary table prepared(value jsonb);grant all on prepared to authenticated;
insert into prepared select public.prepare_publisher_studio_series_v1((select(value->>'seriesId')::uuid from result),1,jsonb_build_array(jsonb_build_object('id',(select value#>>'{projectIds,0}'from result),'draftRevision',0)),pg_temp.uid(60));
select is(jsonb_array_length((select value->'jobs'from prepared)),1,'preparation confirms every selected member');
select is(public.prepare_publisher_studio_series_v1((select(value->>'seriesId')::uuid from result),1,jsonb_build_array(jsonb_build_object('id',(select value#>>'{projectIds,0}'from result),'draftRevision',0)),pg_temp.uid(61)),(select value from prepared),'a second session command reuses the exact draft render');
select is((select count(*)from public.studio_render_jobs where tenant_id=pg_temp.uid(10)),1::bigint,'library selection does not create repeated render jobs');
select is((select count(*)from public.studio_revisions where tenant_id=pg_temp.uid(10)),1::bigint,'library selection does not create repeated Studio versions');
select throws_ok($$select public.prepare_publisher_studio_series_v1((select(value->>'seriesId')::uuid from result),1,jsonb_build_array(jsonb_build_object('id',(select value#>>'{projectIds,0}'from result),'draftRevision',9)),pg_temp.uid(62))$$,'PT409',null,'stale selected content is rejected');
select set_config('request.jwt.claim.sub',pg_temp.uid(3)::text,true);
select throws_ok($$select public.prepare_publisher_studio_series_v1((select(value->>'seriesId')::uuid from result),1,jsonb_build_array(jsonb_build_object('id',(select value#>>'{projectIds,0}'from result),'draftRevision',0)),pg_temp.uid(63))$$,'42501',null,'viewers cannot start a render');
select set_config('request.jwt.claim.sub',pg_temp.uid(2)::text,true);
select throws_ok($$select public.list_publisher_studio_series_v2(pg_temp.uid(10))$$,'42501',null,'tenant B cannot read tenant A documents');
select is((public.list_publisher_studio_series_v2(pg_temp.uid(11))->>'total')::integer,0,'tenant B receives only its own designs');
reset role;
select ok(not has_function_privilege('anon','public.list_publisher_studio_series_v2(uuid,integer,text)','execute'),'anonymous access is denied');
select ok(not has_function_privilege('anon','public.prepare_publisher_studio_series_v1(uuid,bigint,jsonb,uuid)','execute'),'anonymous preparation is denied');
select * from finish();rollback;
